package com.hahhah20.heavenlysworddescent.effect;
import com.hahhah20.heavenlysworddescent.HeavenlySwordDescentPlugin;import org.bukkit.*;
public final class EnergyEffect { public static void tick(HeavenlySwordDescentPlugin p,Location c,int tick){World w=c.getWorld();if(w==null)return;int orbits=p.getConfig().getInt("visual.energy-orbits");for(int ring=0;ring<orbits;ring++){double h=10+ring*2+Math.sin(tick*.16+ring)*.7,r=1.1+ring*.65;for(int i=0;i<8;i++){double a=tick*.12+i*Math.PI/4+ring*.8;w.spawnParticle(Particle.END_ROD,c.clone().add(Math.cos(a)*r,h,Math.sin(a)*r),1);}}if(tick%5==0)w.spawnParticle(Particle.SOUL_FIRE_FLAME,c.clone().add(0,18,0),6,.7,.2,.7,.02);}}
